with lines as (select id, plan, currency, explode_outer(tier_prices) as val from price_tiers) select case when val >= 87 then 'HIGH' else 'LOW' end as val_tier, size(collect_set(currency)) as num_currencies, count_if(currency = 'THB') as thb_events, count(distinct id) as distinct_ids, count_if(plan = 'enterprise') as enterprise_events, sum(val) filter (where plan = 'enterprise') as enterprise_total_val, count(*) as num_rows from lines group by case when val >= 87 then 'HIGH' else 'LOW' end order by num_rows nulls first;
